package glitch

import data.glitch_lib

# Weak algorithms and modes to detect
weak_algorithms := {"DES", "3DES", "RC4", "Blowfish", "MD5", "SHA1", "AES-ECB"}

# Weak protocols to detect
weak_protocols := {"SSLv2", "SSLv3", "TLS_1_0", "TLS_1_1", "HTTP"}

# Weak key derivation functions
weak_kdfs := {"PBKDF1"}

# Minimum allowed key sizes
min_rsa_key_size := 2048
min_aes_key_size := 128

# Attributes that typically define cryptographic settings
crypto_attrs := {"algorithm", "encryption_type", "cipher_suite", "version", "key_length", "key_size", "bit_length", "kdf", "iterations", "cost_factor", "protocol", "ssl_policy", "tls_version", "security_policy", "encryption", "encryption_enabled"}

# Check for weak algorithm strings
check_weak_algorithm(value) {
    value.ir_type == "String"
    alg := upper(value.value)
    weak_algorithms[_] == alg
}

# Check for weak protocols
check_weak_protocol(value) {
    value.ir_type == "String"
    proto := upper(value.value)
    weak_protocols[_] == proto
}

# Check for weak key sizes
check_weak_key_size(value, attr_name) {
    value.ir_type == "Integer"
    attr_name == "key_size"
    value.value < min_rsa_key_size
} else {
    value.ir_type == "Integer"
    attr_name == "key_length"
    value.value < min_rsa_key_size
} else {
    value.ir_type == "Integer"
    attr_name == "bit_length"
    value.value < min_rsa_key_size
} else {
    value.ir_type == "String"
    attr_name == "key_size"
    regex.match(`(?i)RSA-(\d+)`, value.value, matches)
    to_number(matches[1]) < min_rsa_key_size
} else {
    value.ir_type == "String"
    attr_name == "algorithm"
    regex.match(`(?i)AES-(\d+)`, value.value, matches)
    to_number(matches[1]) < min_aes_key_size
}

# Check for weak KDF configurations
check_weak_kdf(value, attr_name) {
    value.ir_type == "String"
    attr_name == "kdf"
    upper(value.value) == "PBKDF1"
} else {
    value.ir_type == "Integer"
    attr_name == "iterations"
    value.value < 100000
} else {
    value.ir_type == "Integer"
    attr_name == "cost_factor"
    value.value < 10
}

# Check for disabled encryption
check_disabled_encryption(value, attr_name) {
    value.ir_type == "Boolean"
    attr_name == "encryption_enabled"
    value.value == false
} else {
    value.ir_type == "String"
    attr_name == "encryption"
    upper(value.value) == "DISABLED"
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == crypto_attrs[_]

    check_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or broken encryption algorithm. (CWE-326)"
    }
}

