package glitch

import data.glitch_lib

# Detects CWE-326: Inadequate Encryption Strength
# Checks for weak algorithms, protocols, key sizes, and hardcoded secrets.

weak_ciphers := {"DES", "3DES", "RC4", "Blowfish", "MD5", "SHA1", "AES-ECB"}
weak_protocols := {"SSLv2", "SSLv3", "TLS_1_0", "TLS_1_1", "HTTP"}

# Check for weak cipher usage in string values
check_weak_cipher(value) {
    value.ir_type == "String"
    regex.match(`(?i)(DES|3DES|RC4|Blowfish|MD5|SHA1|AES-ECB)`, value.value)
}

# Check for weak protocol usage in string values
check_weak_protocol(value) {
    value.ir_type == "String"
    regex.match(`(?i)(SSLv2|SSLv3|TLS[_-]?1[_.]?0|TLS[_-]?1[_.]?1|HTTP(?![Ss]))`, value.value)
}

# Check for insufficient key size in string values (e.g., "AES-128", "RSA-1024")
check_weak_key_size_string(value) {
    value.ir_type == "String"
    regex.match(`(?i)(AES[-_]128|RSA[-_]1024|RSA[-_]512)`, value.value)
}

# Check for insufficient key size in integer values
# Attributes like key_size, key_length, bit_length
check_weak_key_size_int(attr_name, value) {
    value.ir_type == "Integer"
    key_size_attrs := {"key_size", "key_length", "bit_length"}
    key_size_attrs[_] == attr_name
    value.value < 2048
}

# Check for hardcoded secrets (common password patterns or short strings)
check_hardcoded_secret(value) {
    value.ir_type == "String"
    count(value.value) < 8
    regex.match(`(?i)(password|secret|key|token)`, value.value)
}

# Helper to traverse complex values (Hash, Array) for leaf values
traverse_value(value, attr_name) {
    value.ir_type == "String"
    check_weak_cipher(value)
} {
    value.ir_type == "String"
    check_weak_protocol(value)
} {
    value.ir_type == "String"
    check_weak_key_size_string(value)
} {
    value.ir_type == "Integer"
    check_weak_key_size_int(attr_name, value)
} {
    value.ir_type == "String"
    check_hardcoded_secret(value)
} {
    value.ir_type == "Hash"
    count(value.value) > 0
    item := value.value[_]
    traverse_value(item.value, attr_name)
} {
    value.ir_type == "Array"
    count(value.value) > 0
    item := value.value[_]
    traverse_value(item, attr_name)
}

# Detect in AtomicUnits (Ansible, Chef resources)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    traverse_value(attr.value, attr.name)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithm, protocol, or key size detected. (CWE-326)"
    }
}

# Detect in Variables (Chef attributes, Puppet variables)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    traverse_value(var.value, var.name)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic configuration in variable. (CWE-326)"
    }
}

